"""Reader-facing conclusions, standard figure and pending graph binding."""
from dental_release.paths import expand as _release_expand
import datetime, hashlib, json, math, time, csv, re
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT = Path(__file__).resolve().parents[1]

def load(p):
    return json.loads((ROOT / p).read_text())

def sha(p):
    return hashlib.sha256((ROOT / p).read_bytes()).hexdigest()

def save(p, x):
    (ROOT / p).write_text(json.dumps(x, indent=2, ensure_ascii=False, allow_nan=False) + '\n')

def reader_spacing(s):
    for (a, b) in [('Originalets14', 'Original power quantile for 14 groups'), ('vid175', 'at 175'), ('vidR', 'at R'), ('nine bounds', 'nine bounds'), ('provides 0', 'provides 0'), ('from 1', 'from 1'), ('med0', 'with 0'), ('till0', 'to 0'), ('to one', 'to one'), ('the data', 'the data'), ('minskas', 'minskas')]:
        s = s.replace(a, b)
    s = re.sub('(?<![/A-Za-z])(?P<w>at|from|with|for|about|maximum|within|has|needs|and|after|one|gives|all|on)(?=\\d)', '\\g<w> ', s)
    return re.sub('(?<=\\d)(?=N\\b|MPa\\b|mm\\b|s\\b|MiB\\b|rader\\b|observationer\\b|studie\\b|studier\\b|byte\\b)', ' ', s)

def main():
    start = time.perf_counter()
    r1 = load('results_R1.json')
    r2 = load('results_R2.json')
    r3 = load('results_R3.json')
    r4 = load('results_R4.json')
    data = load('raw/published_endpoints.json')
    sources = load('raw/primary_tables.json')
    cost = load('raw/COST.json')
    m = r2['metrics']
    g = m['global']
    s = r4['states']
    corrections = data['identity_corrections']
    primary = ['K1-A1', 'K1-A2', 'K1-A3a', 'K1-A3b', 'K1-A3c', 'N09', 'N13', 'N14', 'N15']
    replay = load('raw/replay.json')
    byid = {x['id']: x for x in data['records']}
    ratio = float(np.median([next((x for x in replay if x['id'] == i))['replayed_N'][1] / byid[i]['force_N'] for i in primary]))
    stress_ratios = [x['mean_plusminus_sd_scenarios_not_confidence_interval'][1]['ratio_to_default'] for x in r3['residual_stress_scenarios'] if x['id'] in primary]
    mutations = [x for r in [r1, r2, r3, r4] for x in r['mutations']]
    all_reject = all((x['injected_error_rejected'] for x in mutations))
    if not all_reject:
        raise ValueError('a corruption did not fail its frozen gate')
    plt.rcParams.update({'font.size': 10, 'axes.spines.top': False, 'axes.spines.right': False})
    (fig, axes) = plt.subplots(1, 3, figsize=(14.5, 4.4), layout='constrained')
    held = r2['held_rows']
    truth = [h['observed_force_N'] for h in held]
    baseline = [h['predictions']['practice']['prediction_N'] for h in held]
    cal = [h['predictions']['global']['prediction_N'] for h in held]
    ax = axes[0]
    ax.scatter(truth, baseline, label='K33 defaults', color='#bd6339', s=35)
    ax.scatter(truth, cal, label='Study held out', color='#235b87', marker='s', s=30)
    ax.plot([40, 600], [40, 600], color='.35', lw=1)
    ax.set(xscale='log', yscale='log', xlabel='Published cyclic endpoint (N)', ylabel='Predicted endpoint (N)', title='External endpoints: 14 groups / 7 studies')
    ax.legend(fontsize=8)
    ax.text(0.02, 0.02, 'Calibration: 2 wrong decided classes\nStrict matching: only 1 study', transform=ax.transAxes, fontsize=8)
    ax = axes[1]
    names = ['External hex', 'Internal double hex']
    ax.bar(names, [190, 150], color=['#3b6b63', '#c78457'])
    ax.axhline(175, color='#7a354d', ls='--', label='175 N bench class')
    ax.scatter(names, [byid['K1-A3a']['legacy_prediction_N'], byid['K1-A3b']['legacy_prediction_N']], c='black', marker='x', s=50, label='K33 defaults')
    ax.set(ylabel='Maximum cyclic force (N)', title='Same 3.5 mm / Ti grade5 / 30° / 5e6')
    ax.legend(fontsize=8)
    ax.text(0.02, 0.02, 'PMC7730231 Table2\nEndpoint support; no risk certificate', transform=ax.transAxes, fontsize=8)
    ax = axes[2]
    from stress_port import force_point
    ratios = np.linspace(0.1, 0.5, 41)
    for (a, color, label) in zip(s, ['#3b6b63', '#79549c'], ['c/g = 0 N', 'c/g = 100 N']):
        curve = [force_point(a['g_MPa_per_N'], a['C_MPa'], a['compression_offset_MPa'], a['alpha'], float(rr)) for rr in ratios]
        ax.plot(ratios, curve, color=color, label=label)
        ax.scatter([0.1, 0.5], [a['reference_force_N'], a['changed_R_force_N']], color=color, s=30)
    ax.set(xlabel='Machine load ratio R', ylabel='Model endpoint (N)', title='Equal force summary fails after R changes')
    ax.legend(fontsize=8)
    ax.text(0.02, 0.02, f"Identity error 0.0 N (bitwise)\nDifference {r4['downstream_difference_N']:.2f} N\nOwn fixture; empirical transfer UNKNOWN", transform=ax.transAxes, fontsize=8)
